1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <meta name="description" content="My Page">
7	  <meta name="robots" content="index, follow">
8	  <meta name="theme-color" content="#ffffff" media="(prefers-color-scheme: light)">
9	  <meta name="theme-color" content="#111214" media="(prefers-color-scheme: dark)">
10	  <meta property="og:title" content="My Page">
11	  <meta property="og:description" content="My Page">
12	  <meta property="og:type" content="website">
13	  <link rel="canonical" href="https://example.com/">
14	  <link rel="icon" href="data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 16 16%22><circle cx=%228%22 cy=%228%22 r=%227%22 fill=%22%232563eb%22/></svg>">
15	  <title>My Page</title>
16	  <style>
17	    :root {
18	      color-scheme: light dark;
19	      --bg: #ffffff;
20	      --fg: #1a1a1a;
21	      --muted: #555;
22	      --accent: #2563eb;
23	      --border: #e5e7eb;
24	    }
25	
26	    @media (prefers-color-scheme: dark) {
27	      :root {
28	        --bg: #111214;
29	        --fg: #e8e8e8;
30	        --muted: #aaa;
31	        --accent: #60a5fa;
32	        --border: #2a2b2e;
33	      }
34	    }
35	
36	    * {
37	      box-sizing: border-box;
38	    }
39	
40	    html {
41	      scroll-behavior: smooth;
42	    }
43	
44	    @media (prefers-reduced-motion: reduce) {
45	      html {
46	        scroll-behavior: auto;
47	      }
48	    }
49	
50	    ::selection {
51	      background: var(--accent);
52	      color: var(--bg);
53	    }
54	
55	    body {
56	      font-family: system-ui, -apple-system, sans-serif;
57	      max-width: 40rem;
58	      margin: 3rem auto;
59	      padding: 0 1rem;
60	      line-height: 1.6;
61	      color: var(--fg);
62	      background: var(--bg);
63	    }
64	
65	    @media (max-width: 30rem) {
66	      body {
67	        margin: 1.5rem auto;
68	      }
69	    }
70	
71	    h1 {
72	      font-size: 2rem;
73	      margin-bottom: 0.5rem;
74	    }
75	
76	    p {
77	      color: var(--muted);
78	      max-width: 34rem;
79	    }
80	
81	    a {
82	      color: var(--accent);
83	      transition: opacity 0.15s ease;
84	    }
85	
86	    a:hover {
87	      opacity: 0.8;
88	    }
89	
90	    a:focus-visible,
91	    button:focus-visible {
92	      outline: 2px solid var(--accent);
93	      outline-offset: 2px;
94	    }
95	
96	    .skip-link {
97	      position: absolute;
98	      left: -9999px;
99	      top: 0;
100	      background: var(--accent);
101	      color: var(--bg);
102	      padding: 0.5rem 1rem;
103	      border-radius: 0.25rem;
104	      z-index: 10;
105	    }
106	
107	    .skip-link:focus {
108	      left: 1rem;
109	      top: 1rem;
110	    }
111	
112	    nav ul {
113	      display: flex;
114	      gap: 1rem;
115	      list-style: none;
116	      padding: 0;
117	      margin: 0 0 2rem;
118	    }
119	
120	    nav a {
121	      text-decoration: none;
122	      font-weight: 500;
123	      opacity: 1;
124	    }
125	
126	    nav a:hover {
127	      text-decoration: underline;
128	    }
129	
130	    nav a[aria-current="page"] {
131	      text-decoration: underline;
132	      color: var(--fg);
133	    }
134	
135	    h2 {
136	      margin-top: 2rem;
137	      margin-bottom: 0.5rem;
138	    }
139	
140	    section + section {
141	      margin-top: 1.5rem;
142	    }
143	
144	    footer {
145	      margin-top: 3rem;
146	      padding-top: 1.5rem;
147	      border-top: 1px solid var(--border);
148	      font-size: 0.875rem;
149	      color: var(--muted);
150	    }
151	  </style>
152	</head>
153	<body>
154	  <a class="skip-link" href="#main">Skip to content</a>
155	  <nav aria-label="Primary">
156	    <ul>
157	      <li><a href="#home" data-nav-link>Home</a></li>
158	      <li><a href="#about" data-nav-link>About</a></li>
159	      <li><a href="#contact" data-nav-link>Contact</a></li>
160	    </ul>
161	  </nav>
162	  <main id="main">
163	    <section id="home" aria-labelledby="home-heading">
164	      <h1 id="home-heading">My Page</h1>
165	      <p>Welcome. This page is a starting point — replace this text with your own content.</p>
166	    </section>
167	
168	    <section id="about" aria-labelledby="about-heading">
169	      <h2 id="about-heading">About</h2>
170	      <p>Add a short description of what this page or project is about here.</p>
171	    </section>
172	
173	    <section id="contact" aria-labelledby="contact-heading">
174	      <h2 id="contact-heading">Contact</h2>
175	      <p>Reach out at <a href="mailto:hello@example.com">hello@example.com</a>.</p>
176	    </section>
177	  </main>
178	  <footer>
179	    <p>&copy; <span id="year"></span> My Page. All rights reserved.</p>
180	  </footer>
181	  <script>
182	    document.getElementById('year').textContent = String(new Date().getFullYear());
183	
184	    const navLinks = document.querySelectorAll('[data-nav-link]');
185	    const sections = [...navLinks].map(link => document.querySelector(link.getAttribute('href')));
186	
187	    const setActive = (id) => {
188	      navLinks.forEach(link => {
189	        if (link.getAttribute('href') === `#${id}`) {
190	          link.setAttribute('aria-current', 'page');
191	        } else {
192	          link.removeAttribute('aria-current');
193	        }
194	      });
195	    };
196	
197	    if ('IntersectionObserver' in window) {
198	      const observer = new IntersectionObserver((entries) => {
199	        const visible = entries
200	          .filter(entry => entry.isIntersecting)
201	          .sort((a, b) => b.intersectionRatio - a.intersectionRatio)[0];
202	        if (visible) setActive(visible.target.id);
203	      }, { rootMargin: '-40% 0px -50% 0px' });
204	      sections.forEach(section => section && observer.observe(section));
205	    } else {
206	      setActive(sections[0]?.id);
207	    }
208	  </script>
209	</body>
210	</html>
